<title>角色状态</title>
<style>
    :root {
        --bar-bg-color: #444;
        --bar-height: 18px;
        --bar-border-radius: 5px;
        --font-color: #fff;
        --font-size: 12px;
        --affection-color: #ff69b4;
        --lust-color: #ff4500;
        --corruption-color: #8a2be2;
        --loyalty-color: #1e90ff;
    }
    body {
        font-family: 'Microsoft YaHei', sans-serif;
        background-color: rgba(0, 0, 0, 0.7);
        color: var(--font-color);
        padding: 8px;
        border-radius: 10px;
    }
    .status-bar-container {
        display: grid;
        grid-template-columns: 1fr 3fr;
        gap: 5px 10px;
        align-items: center;
        margin-bottom: 5px;
    }
    .status-bar-label {
        font-size: var(--font-size);
        font-weight: bold;
        text-align: right;
    }
    .status-bar {
        width: 100%;
        height: var(--bar-height);
        background-color: var(--bar-bg-color);
        border-radius: var(--bar-border-radius);
        overflow: hidden;
        position: relative;
    }
    .status-bar-fill {
        height: 100%;
        border-radius: var(--bar-border-radius);
        transition: width 0.5s ease-in-out;
        display: flex;
        align-items: center;
        justify-content: center;
    }
    .status-bar-text {
        font-size: var(--font-size);
        font-weight: bold;
        position: absolute;
        width: 100%;
        text-align: center;
        line-height: var(--bar-height);
        text-shadow: 1px 1px 2px rgba(0,0,0,0.7);
    }
    #affection .status-bar-fill { background-color: var(--affection-color); }
    #lust .status-bar-fill { background-color: var(--lust-color); }
    #corruption .status-bar-fill { background-color: var(--corruption-color); }
    #loyalty .status-bar-fill { background-color: var(--loyalty-color); }
</style>
</head>
<body>

<div id="status-display">
    <!-- 状态栏将由脚本动态生成 -->
</div>

<script>
    // 模拟变量，实际使用时请替换为从SillyTavern获取的变量
    const charState = {
        an_Affection: { "林软软": 10, "夏水水": 5, "苏媚": 20 },
        an_Lust: { "林软软": 20, "夏水水": 30, "苏媚": 5 },
        an_Corruption: { "林软软": 15, "夏水水": 25, "苏媚": 0 },
        an_Loyalty: { "林软软": 80, "夏水水": 85, "苏媚": 95 }
    };

    const statusConfig = {
        an_Affection: { label: '好感', color: 'var(--affection-color)', max: 200, min: -100 },
        an_Lust: { label: '欲望', color: 'var(--lust-color)', max: 100, min: 0 },
        an_Corruption: { label: '堕落', color: 'var(--corruption-color)', max: 100, min: 0 },
        an_Loyalty: { label: '忠诚', color: 'var(--loyalty-color)', max: 100, min: 0 }
    };

    function createStatusBar(charName, varName, value) {
        const config = statusConfig[varName];
        if (!config) return '';

        const range = config.max - config.min;
        const percentage = ((value - config.min) / range) * 100;

        return `
            <div class="status-bar-container" id="${varName.toLowerCase()}">
                <div class="status-bar-label">${config.label}</div>
                <div class="status-bar" title="${config.label}: ${value}">
                    <div class="status-bar-fill" style="width: ${percentage}%; background-color: ${config.color};"></div>
                    <div class="status-bar-text">${charName} ${value}</div>
                </div>
            </div>
        `;
    }

    function updateStatusBars() {
        const display = document.getElementById('status-display');
        let html = '';

        // 遍历所有在场的角色，并为她们生成状态栏
        // 这里简单处理，只显示好感度大于-100的角色
        const presentCharacters = new Set();
        for (const varName in charState) {
            for (const charName in charState[varName]) {
                if (charState.an_Affection[charName] > -100) {
                    presentCharacters.add(charName);
                }
            }
        }

        presentCharacters.forEach(charName => {
            html += `<h4>${charName}</h4>`;
            for (const varName in statusConfig) {
                if (charState[varName] && charState[varName][charName] !== undefined) {
                    html += createStatusBar(charName, varName, charState[varName][charName]);
                }
            }
        });

        display.innerHTML = html;
    }

    // 暴露一个函数给SillyTavern调用
    // 在SillyTavern的extensions settings中，Update Function填入 "updateFromST"
    function updateFromST(jsonString) {
        try {
            const data = JSON.parse(jsonString);
            // 假设SillyTavern传递的变量格式与charState一致
            Object.assign(charState, data);
            updateStatusBars();
        } catch (e) {
            console.error("Failed to parse JSON from SillyTavern:", e);
        }
    }

    // 初始加载
    updateStatusBars();

</script>
</body>
</html>

