    function loadState() { try { const savedState = localStorage.getItem(UI_STATE_KEY); if (savedState) uiState = { ...uiState, ...JSON.parse(savedState) }; } catch (e) { console.warn("无法加载UI状态:", e); } }

    function applyScale(scale) {
        const root = document.documentElement;
        const display = document.getElementById('font-size-display');
        scale = Math.max(0.7, Math.min(1.5, scale));
        root.style.fontSize = `${16 * scale}px`;
        if(display) display.textContent = `${Math.round(scale * 100)}%`;
        uiState.scale = scale;
        saveState();
    }

    function createEmptyState(message) {
        return `<div class="empty-state-placeholder">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 13h6m-3-3v6m-9 1V7a2 2 0 012-2h6l2 2h6a2 2 0 012 2v8a2 2 0 01-2 2H5a2 2 0 01-2-2z" /></svg>
            <p>${message}</p>
        </div>`;
    }

    function selectOption(buttonElement) {
        document.querySelectorAll('#main_story_options .option-button').forEach(btn => btn.classList.remove('active'));
        buttonElement.classList.add('active');

        let textToInsert = buttonElement.textContent.trim();
        textToInsert = textToInsert.replace(/\(.*?\)|（.*?）|\[.*?\]|【.*?】|\{.*?\}/g, '').trim();

        if (!textToInsert) return;

        try {
            const input = window.parent.document.querySelector('#send_textarea');
            if (input) {
                const currentValue = input.value.trim();
                input.value = currentValue ? `${currentValue}\n${textToInsert}` : textToInsert;
                input.dispatchEvent(new Event('input', { bubbles: true }));
                input.focus();
            } else {
                console.warn('SillyTavern input field #send_textarea not found.');
            }
        } catch (error) {
            console.error('Error accessing parent window input:', error);
            alert('无法访问输入框。这可能是由于浏览器安全策略。');
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        try {
            loadState(); renderAll(); setupEventListeners(); applyScale(uiState.scale);
        } catch (e) {
            const container = document.querySelector('.main-container');
            if (container) container.innerHTML = `<div style="color: #F7768E; padding: 1.25rem; text-align: center;"><h3>UI渲染失败</h3><p>请检查控制台以获取详细错误信息。</p><div style="text-align:left; white-space:pre-wrap; background: rgba(0,0,0,0.2); padding: 1rem; border-radius: 0.5rem; font-size: 0.8rem; max-height: 200px; overflow-y: auto;">${e.stack}</div></div>`;
            console.error("UI初始化时发生严重错误:", e);
        }
    });

    const getCleanedRawContent = id => document.getElementById(id)?.innerHTML || "";
    const setContent = (id, html) => { const el = document.getElementById(id); if (el) el.innerHTML = html; };

    function createListItemHTML(label, value, extraClass = '') {
      let cleanedValue = String(value || '').trim();
       if (!cleanedValue || INVALID_VALUES.some(invalid => cleanedValue.startsWith(invalid))) return '';
      let valPart = cleanedValue; let descPart = '';
      const descMatch = cleanedValue.match(/(?:\(|\[)\s*描述：\s*([^\])]+)\s*(?:\)|\])/);
      if (descMatch) {
          descPart = descMatch[1].trim(); valPart = cleanedValue.replace(descMatch[0], '').trim();
          if (NUMERIC_LABELS.includes(label) && INVALID_VALUES.some(invalid => descPart.startsWith(invalid))) return '';
      }
      valPart = valPart.replace(/\*/g, '').trim();
      if (!valPart) return '';
      if (label === '即时感想') extraClass += ' player-thought';
      let itemHtml = `<strong>${label}</strong><span class="${extraClass}">${valPart}</span>`;
      if (descPart) itemHtml += `<span class="item-desc">${descPart}</span>`;
      return `<div class="info-card">${itemHtml}</div>`;
    }

    function setupEventListeners() {
      document.querySelectorAll('.tab-button').forEach(button => {
        button.addEventListener('click', function() {
          if (this.classList.contains('active')) return;
          document.querySelectorAll('.tab-button.active').forEach(btn => btn.classList.remove('active'));
          this.classList.add('active');
          document.querySelectorAll('.content-panel').forEach(panel => panel.style.display = 'none');
          const targetPanel = document.getElementById(this.dataset.target);
          if (targetPanel) targetPanel.style.display = 'block';
        });
      });

      document.getElementById('detail-tabs-container')?.addEventListener('click', function(e) {
        if (e.target.matches('.detail-tab') && !e.target.classList.contains('active')) {
           this.querySelectorAll('.detail-tab').forEach(t => t.classList.remove('active'));
           e.target.classList.add('active');
           currentDetailSection = e.target.dataset.section;
           if (selectedCharacterIndex > -1) renderCharacterDetailSection(currentCharacters[selectedCharacterIndex]);
        }
      });

      const modal = document.getElementById('avatar-modal');
      if (modal) modal.addEventListener('click', () => modal.classList.remove('show'));
    }

    function showAvatarModal(url) {
        const modal = document.getElementById('avatar-modal');
        const img = document.getElementById('modal-avatar-img');
        if (modal && img && url && !INVALID_VALUES.some(invalid => url.includes(invalid))) {
            const cleanedUrl = url.trim().replace(/`/g, '');
            img.src = cleanedUrl; modal.classList.add('show');
        }
    }

    function extractData(rawBlock) {
        const data = {}; if (!rawBlock) return data;
        const lines = rawBlock.split('\n');
        for (const line of lines) {
            const match = line.match(/^([^:]+):([\s\S]*)/);
            if (match && match[1] && match[2] !== undefined) {
                data[match[1].trim()] = match[2].trim();
            }
        }
        return data;
    }

    function renderAll() {
        renderTopInfoBar(); renderMainContent(); renderProfileContent(); renderLogContent();
        renderTasksContent(); renderSystemContent(); renderStatusContent();
    }

    function renderTopInfoBar() {
        const data = extractData(getCleanedRawContent('raw-inventory'));
        document.getElementById('info-time').textContent = data['时间'] || '未知';
        document.getElementById('info-location').textContent = data['地点'] || '未知';
    }

    function renderMainContent() {
        let mainText = getCleanedRawContent('raw-mainbody');
        mainText = mainText.replace(/<mainbody>[\s\S]*?<\/mainbody>|<br\s*\/?>/gi, '').replace(/<!--[\s\S]*?-->/g, '').replace(/(\r\n|\n|\r){2,}/g, '\n').trim();
        mainText = mainText.replace(/「([^」]+)」|“([^”]+)”|"([^"]+)"/g, (_, p1, p2, p3) => `<span class="highlight-quote">「${p1 || p2 || p3}」</span>`);
        mainText = mainText.replace(/<em>([\s\S]*?)<\/em>|\*([^*]+)\*/g, (_, em, bold) => `<em class="player-thought">${em || bold}</em>`);
        setContent('main_story_text', mainText);

        const rawOptions = getCleanedRawContent('raw-options');
        const optionsContainer = document.getElementById('main_story_options');
        if (!optionsContainer) return;

        let optionsHtml = '';
        if (rawOptions && rawOptions.trim()) {
            const lines = rawOptions.trim().split('\n').filter(line => line.trim());
            let renderedOptions = '';
            lines.forEach(line => {
                const match = line.trim().match(/^\s*\d+\.\s*(.*)/);
                if (match && match[1]) {
                    const optionText = match[1].trim();
                     if (optionText) {
                        renderedOptions += `<button class="option-button" onclick="selectOption(this)">${optionText}</button>`;
                    }
                }
            });
            if (renderedOptions) {
                optionsHtml = `<div class="options-list">${renderedOptions}</div>`;
            }
        }
        setContent('main_story_options', optionsHtml);
    }

    function renderProfileContent() {
        const data = extractData(getCleanedRawContent('raw-rin-content'));
        const createCardItem = (label, valueKey) => {
            const value = data[valueKey];
            if (!value || INVALID_VALUES.some(invalid => String(value).includes(invalid))) return '';
            const finalValue = String(value).replace(/<em>([\s\S]*?)<\/em>|\*([^*]+)\*/g, (_, em, bold) => `<em class="player-thought">${em || bold}</em>`);
            return `<div class="info-card"><strong>${label}</strong><span>${finalValue}</span></div>`;
        }
        let infoHtml = createCardItem('我的身份', '我的身份') + createCardItem('我的心境', '我的心境') + createCardItem('持有物', '持有物') + createCardItem('我的心声', '我的心声');
        const gridHtml = createCardItem('核心能力', '核心能力') + createCardItem('熟练等级', '熟练等级') + createCardItem('表现力', '表现力');
        setContent('profile-content', `<div class="unified-section"><div class="data-section"><div class="user_avatar" style="width: 80px; height: 80px; border-radius: 50%; margin: 0 auto 1rem; background-size: cover; background-position: center; border: 2px solid var(--border-color-strong); cursor: pointer;"></div><h3 style="text-align:center; margin:0;">个人资料</h3></div><div class="info-grid">${infoHtml}</div><div class="info-grid">${gridHtml}</div><div class="data-section"><span class="data-title">羁绊列表</span><div class="data-list" style="white-space: pre-wrap; padding:0.625rem;">${data['羁绊列表'] || '暂无羁绊'}</div></div></div>`);
        document.querySelector('#profile-content .user_avatar')?.addEventListener('click', e => { e.stopPropagation(); const url = window.getComputedStyle(e.target).backgroundImage.slice(5, -2); if (url) showAvatarModal(url); });
    }
    function renderLogContent(){
        const data = extractData(getCleanedRawContent('raw-inventory'));
        const regionHtml = createListItemHTML('区域', data['区域']);
        const eventHtml = createListItemHTML('当前事件', data['当前事件']);
        const reviewHtml = createListItemHTML('剧情回顾', data['剧情回顾']);
        const content = [regionHtml, eventHtml, reviewHtml].filter(Boolean).join('');
        setContent('log-content', `<div class="unified-section"><div class="data-section"><h3 style="text-align:center; margin-top:0;">情报日志</h3></div>${content ? `<div class="info-grid">${content}</div>` : createEmptyState('暂无情报日志')}`);
    }
    function renderTasksContent(){
        const data = extractData(getCleanedRawContent('raw-quests'));
        const createQuestBar = (titleKey, progressKey, titleLabel) => {
            const title = data[titleKey];
            if(!title || INVALID_VALUES.some(invalid => title.includes(invalid))) return '';
            const progressValue = parseFloat(data[progressKey]) || 0;
            return `<div class="data-section"><span class="data-title" style="margin-bottom: 0.5rem;">${titleLabel}</span><p style="border:none; padding-bottom:0.5rem; margin:0.5rem 0;">${title}</p><div style="text-align: right; color: var(--text-secondary); font-size: 0.9em; margin-bottom: 0.3rem;">${progressValue}%</div><div class="progress-bar" style="background: var(--bg-main); border-radius: 5px; height: 8px; overflow: hidden; border: 1px solid var(--border-color);"><div class="progress-fill" style="width: ${progressValue}%; background: var(--accent-blue); height: 100%; transition: width 0.5s ease;"></div></div></div>`;
        };
        const quests = [createQuestBar('主线故事', '主线进度', '主线故事'), createQuestBar('支线事件', '支线进度', '支线事件'), createQuestBar('最终结局', '结局进度', '最终结局')].filter(Boolean).join('');
        setContent('tasks-content', `<div class="unified-section"><div class="data-section"><h3 style="text-align:center; margin-top:0;">任务手册</h3></div>${quests || createEmptyState('当前没有任务')}`);
    }

    function renderSystemContent() {
        const rawContent = getCleanedRawContent('raw-system');
        const data = extractData(rawContent);
        const settingsHtml = `<div class="data-section"><span class="data-title">界面设置</span><div class="setting-controls flex-center"><button id="font-decrease" title="减小字体">-</button><span id="font-size-display">100%</span><button id="font-increase" title="增大字体">+</button><button id="font-reset">重置</button></div></div>`;
        const coreHtml = createListItemHTML('已解锁功能', data['系统助手-已解锁功能']);
        const energyHtml = createListItemHTML('当前命运点数', data['当前命运点数']);
        const mainQuestHtml = createListItemHTML('系统发布的主线任务', data['系统发布的主线任务']);

        let sideQuestHtml = '';
        const sideQuestKey = '系统发布的支线/奇遇任务:';
        const sideQuestIndex = rawContent.indexOf(sideQuestKey);

        if (sideQuestIndex !== -1) {
            let questBlock = rawContent.substring(sideQuestIndex + sideQuestKey.length).trim();
            questBlock = questBlock.replace(/^{{|}}$/g, '').trim();

            const tasks = questBlock.split(/(?=\[任务\d+\])/).filter(t => t.trim());

            tasks.forEach(taskText => {
                const nameMatch = taskText.match(/任务名称:\s*([\s\S]*?)(?=\n任务描述:|\n任务奖励:|\n失败惩罚:|$)/);
                const descMatch = taskText.match(/任务描述:\s*([\s\S]*?)(?=\n任务奖励:|\n失败惩罚:|$)/);
                const rewardMatch = taskText.match(/任务奖励:\s*([\s\S]*?)(?=\n失败惩罚:|$)/);
                const penaltyMatch = taskText.match(/失败惩罚:\s*([\s\S]*?)$/);

                const name = nameMatch ? nameMatch[1].trim() : null;
                const desc = descMatch ? descMatch[1].trim() : null;
                const reward = rewardMatch ? rewardMatch[1].trim() : null;
                const penalty = penaltyMatch ? penaltyMatch[1].trim() : null;

                if (name && !INVALID_VALUES.some(invalid => name.includes(invalid))) {
                    let itemHtml = `<div class="quest-item" style="margin-bottom: 1rem; padding: 1rem; border: 1px solid var(--border-color); border-radius: 0.625rem;">`;
                    itemHtml += `<strong style="color: var(--text-title); font-size: 1.05rem; display: block; margin-bottom: 0.5rem;">${name}</strong>`;
                    if (desc && !INVALID_VALUES.some(invalid => desc.includes(invalid))) itemHtml += `<p style="margin: 0.25rem 0;"><strong>描述：</strong>${desc}</p>`;
                    if (reward && !INVALID_VALUES.some(invalid => reward.includes(invalid))) itemHtml += `<p style="margin: 0.25rem 0; color: var(--accent-gold);"><strong>奖励：</strong>${reward}</p>`;
                    if (penalty && !INVALID_VALUES.some(invalid => penalty.includes(invalid))) itemHtml += `<p style="margin: 0.25rem 0; color: var(--accent-lewd);"><strong>惩罚：</strong>${penalty}</p>`;
                    itemHtml += `</div>`;
                    sideQuestHtml += itemHtml;
                }
            });
        }

        setContent('system-content',`<div class="unified-section"><div class="data-section"><h3 style="text-align:center; margin-top:0;">系统功能</h3></div>${settingsHtml}${coreHtml ? `<div class="info-grid">${coreHtml}</div>` : ''}${energyHtml ? `<div class="info-grid">${energyHtml}</div>` : ''}${mainQuestHtml ? `<div class="data-section"><div class="info-grid">${mainQuestHtml}</div></div>` : ''}${sideQuestHtml ? `<div class="data-section"><span class="data-title">当前任务</span><div class="quest-list">${sideQuestHtml}</div></div>` : ''}</div>`);
        document.getElementById('font-increase')?.addEventListener('click', () => applyScale(uiState.scale + 0.05));
        document.getElementById('font-decrease')?.addEventListener('click', () => applyScale(uiState.scale - 0.05));
        document.getElementById('font-reset')?.addEventListener('click', () => applyScale(1.0));
    }

    function renderStatusContent() {
        const rawStatus = getCleanedRawContent('raw-statusbar');
        const selector = document.getElementById('character-selector');
        const detailContent = document.getElementById('detail-content');
        if (!selector || !detailContent) return;

        detailContent.innerHTML = createEmptyState('选择一名角色以查看其详细档案…');

        if (!rawStatus) { selector.innerHTML = createEmptyState('无角色档案'); return; }
        const characterBlocks = rawStatus.split(/\n\s*(?=[a-z]_姓名:)/).filter(b => b.trim());
        currentCharacters = [];
        characterBlocks.forEach(block => {
            const charData = extractData(block);
            const prefixKey = Object.keys(charData).find(k => k.endsWith('_姓名'));
            if(prefixKey) currentCharacters.push({ prefix: prefixKey.substring(0, 2), data: charData });
        });

        if (currentCharacters.length === 0) { selector.innerHTML = createEmptyState('无有效角色档案'); return; }
        renderCharacterSelector();
        selectCharacter(selectedCharacterIndex >= 0 && selectedCharacterIndex < currentCharacters.length ? selectedCharacterIndex : 0);
    }

    function renderCharacterSelector() {
        const selectorContainer = document.getElementById('character-selector');
        if (!selectorContainer) return;
        selectorContainer.innerHTML = currentCharacters.map((char, index) => {
            const name = char.data[`${char.prefix}姓名`] || '未知';
            const avatarKey = Object.keys(char.data).find(k => k.startsWith(char.prefix) && k.endsWith('立绘'));
            const avatarUrl = avatarKey ? char.data[avatarKey] : '';
            const cleanedUrl = (avatarUrl || '').trim().replace(/`/g, '');
            const avatarStyle = (cleanedUrl && !INVALID_VALUES.some(invalid => cleanedUrl.includes(invalid))) ? `style="background-image: url('${cleanedUrl}')"` : '';
            return `<div class="char-select-card" data-index="${index}"><div class="char-select-avatar" ${avatarStyle}></div><span class="char-select-name">${name}</span></div>`;
        }).join('');
        selectorContainer.querySelectorAll('.char-select-card').forEach(el =>
            el.addEventListener('click', (e) => selectCharacter(parseInt(e.currentTarget.dataset.index)))
        );
    }

    function selectCharacter(index) {
        const charDisplay = document.getElementById('character-display');
        const detailTabs = document.getElementById('detail-tabs-container');
        if (!charDisplay || !detailTabs) return;
        if (index < 0 || index >= currentCharacters.length) {
            charDisplay.style.display = 'none'; detailTabs.style.display = 'none';
            setContent('detail-content', createEmptyState('选择一名角色以查看其详细档案…'));
            selectedCharacterIndex = -1; return;
        };
        selectedCharacterIndex = index; const char = currentCharacters[index]; const { prefix, data } = char;
        document.querySelectorAll('.char-select-card').forEach((el, i) => el.classList.toggle('active', i === index));
        charDisplay.style.display = 'block'; detailTabs.style.display = 'flex';
        document.getElementById('selected-name').textContent = `${data[`${prefix}姓名`] || '未知'}`;
        const avatarEl = document.getElementById('selected-avatar');
        const avatarKey = Object.keys(data).find(k => k.startsWith(prefix) && k.endsWith('立绘'));
        const imageUrl = avatarKey ? data[avatarKey] : '';
        if (imageUrl && !INVALID_VALUES.some(invalid => imageUrl.includes(invalid))) {
            const cleanedUrl = imageUrl.trim().replace(/`/g, '');
            avatarEl.style.backgroundImage = `url('${cleanedUrl}')`;
            avatarEl.onclick = (e) => { e.stopPropagation(); showAvatarModal(cleanedUrl); };
        } else { avatarEl.style.backgroundImage = 'none'; }
        renderCharacterDetailSection(char);
    }

    function renderCharacterDetailSection(char) {
        const contentEl = document.getElementById('detail-content'); if (!contentEl || !char) return;
        const { prefix, data } = char;
        const fields = {
            basic: [{ label: '姓名/昵称'}, { label: '地点' }, { label: '当前姿态'}, { label: '好感度'}, { label: '忠诚度' }, { label: '欲望值', class: 'lewd-item' }, { label: '堕落度', class: 'lewd-item' }, { label: '恶趣味' }, { label: '当前状态' }, { label: '即时感想' }],
            attire: [{ label: '整体印象'}, { label: '外套' }, { label: '上衣' }, { label: '内衣', class: 'lewd-item'}, { label: '内裤', class: 'lewd-item' }, { label: '下身着装' }, { label: '鞋子' }, { label: '饰品/持有物' }],
            body: [{ 'label': '嘴唇'}, { 'label': '胸部', class: 'lewd-item' }, { 'label': '三围' }, { 'label': '手' }, { 'label': '腰' }, { 'label': '臀部', class: 'lewd-item' }, { 'label': '腿' }, { 'label': '脚' }],
            secret: [{ label: '小穴', class: 'lewd-item' }, { label: '菊穴', class: 'lewd-item' }, { label: '体内精液', class: 'lewd-item' }, { label: '子宫', class: 'lewd-item' }, { label: '受孕状态', class: 'lewd-item' }, { label: '上次记录', class: 'lewd-item' }]
        };
        const sectionFields = fields[currentDetailSection] || [];
        let html = sectionFields.map(field => {
            const key = `${prefix}${field.label.split('/')[0]}`;
            // Use a more direct key access
            const value = data[key];
            return createListItemHTML(field.label, value, field.class || '');
        }).join('');

        if (!html.trim()) {
            contentEl.innerHTML = createEmptyState('此分类下无相关信息');
        } else {
            contentEl.innerHTML = `<div class="info-grid">${html}</div>`;
        }
        contentEl.style.animation = 'none';
        requestAnimationFrame(() => { contentEl.style.animation = 'detailContentEnter 0.4s ease-out forwards'; });
    }
  </script>
</body>
</html>
