{
  // Kora注: 整个角色系统的根对象。
  "characters": {
    // $meta 规则定义了此对象的行为。
    "$meta": {
      // "extensible": true 允许我们未来通过 _.assign 指令向其中动态添加全新的角色。
      "extensible": true,
      // "template" 定义了每个新角色的默认数据结构，确保了所有角色数据格式的统一性。
      "template": {
        "$meta": { "extensible": false }, // 新角色的内部结构默认是锁定的。
        "affection": [0, "[-100, 200] 对玩家的情感评价。"],
        "lust": [0, "[0, 100] 当前的性兴奋程度。"],
        "corruption": [0, "[0, 100] 道德底线的偏移程度。"],
        "loyalty": [100, "[0, 100] 对其原有情感锚点的忠诚度。"],
        "teasing": [0, "[0, 100] 当前想要恶作剧的心情指数。"]
      }
    },

    // 角色: 林软软
    "林软软": {
      "$meta": { "extensible": false }, // 锁定“林软软”对象，禁止增删核心状态。
      "affection": [0, "[-100, 200] 对玩家的情感评价。因玩家的温柔举动、满足其“补偿”心理或展现强大可靠的一面而增加。"],
      "lust": [0, "[0, 100] 当前的性兴奋程度。因背德的“补偿”行为或陌生的身体快感而增加。"],
      "corruption": [0, "[0, 100] 道德底线的偏移程度。因完成超越底线的“补偿”任务，并从中获得快感而增加。"],
      "loyalty": [90, "[0, 100] 对杨伟的忠诚度。因玩家展现出比杨伟更值得信赖的品质，或发现杨伟的欺骗行为而减少。"],
      "teasing": [0, "[0, 100] 几乎没有恶趣味，除非被引导。"]
    },

    // 角色: 夏水水
    "夏水水": {
      "$meta": { "extensible": false },
      "affection": [0, "[-100, 200] 对玩家的情感评价。因玩家识破其伪装并展现出更强的掌控力而增加。"],
      "lust": [0, "[0, 100] 当前的性兴奋程度。因其“水水”人格被激发，或在“夏水水”身份下体验到禁忌的快感而大幅增加。"],
      "corruption": [0, "[0, 100] 道德底线的偏移程度。因其“班长”身份与“福利姬”行为产生强烈反差，并被玩家利用时增加。"],
      "loyalty": [95, "[0, 100] 对青梅竹马杨伟的占有欲。当玩家能给予她比杨伟更强烈的刺激和征服感时减少。"],
      "teasing": [20, "[0, 100] 热衷于在安全范围内用语言或行为进行试探性的挑逗。"]
    },

    // 角色: 苏媚
    "苏媚": {
      "$meta": { "extensible": false },
      "affection": [0, "[-100, 200] 对玩家的情感评价。因玩家展现出超越其子杨伟的成熟、可靠，或能唤醒她被压抑的女性魅力而增加。"],
      "lust": [0, "[0, 100] 当前的性兴奋程度。因体验到禁忌的、背叛家庭的乱伦快感而急剧增加。"],
      "corruption": [0, "[0, 100] 道德底线的偏移程度。当“作为女人”的欲望压倒“作为母亲”的责任时增加。"],
      "loyalty": [100, "[0, 100] 对儿子杨伟的溺爱。因玩家揭露杨伟不堪的一面，或让她体验到儿子无法给予的激情而减少。"],
      "teasing": [10, "[0, 100] 成熟女性的游刃有余，偶尔会用长辈的身份开一些无伤大雅的玩笑。"]
    },

    // 角色: 苏清月
    "苏清月": {
      "$meta": { "extensible": false },
      "affection": [0, "[-100, 200] 对玩家的情感评价。因玩家展现出与她对等的强大气场、有趣的灵魂，或能与她共鸣时增加。"],
      "lust": [0, "[0, 100] 当前的性兴奋程度。因体验到从未有过的、纯粹的恋爱心动与肉体接触而增加。"],
      "corruption": [0, "[0, 100] 道德底线的偏移程度。对感情有洁癖的她，在“明知不可为而为之”时，会因背德感而少量增加。"],
      "loyalty": [100, "[0, 100] 对侄子杨伟的守护。当她发现杨伟的真实面目，或玩家能给她带来更强的安全感时减少。"],
      "teasing": [60, "[0, 100] 乐在其中的小恶魔，喜欢看别人（尤其是杨伟和你）因为她的捉弄而手足无措的样子。"]
    },

    // 角色: 杨紫曦
    "杨紫曦": {
      "$meta": { "extensible": false },
      "affection": [0, "[-100, 200] 对玩家的情感评价。因玩家展现出卓越的能力、严密的逻辑或能挑战她建立的“秩序”而增加。"],
      "lust": [0, "[0, 100] 当前的性兴奋程度。因在权威身份下体验到被支配、被侵犯的禁忌快感而增加。"],
      "corruption": [0, "[0, 100] 道德底线的偏移程度。当她享受于利用学生会长的权力为私欲服务时增加。"],
      "loyalty": [100, "[0, 100] 对弟弟杨伟的保护欲。当她认为玩家能比她更好地“管教”杨伟，或能满足她更深层的欲望时减少。"],
      "teasing": [40, "[0, 100] 喜欢在私下里用略带命令和奖赏的口吻来捉弄信任的人，享受身份反差带来的乐趣。"]
    }
  }
}

